import os, urllib.request, re, collections, itertools
base=os.environ['GALAXY_URL'].rstrip('/')
with open(os.environ['GALAXY_API_KEY_FILE']) as f: key=f.read().strip()
dsid='f9cad7b01a472135156bb13095ae0294'
req=urllib.request.Request(f'{base}/api/datasets/{dsid}/display', headers={'x-api-key':key})
with urllib.request.urlopen(req) as r: text=r.read().decode()
sites=[('s1',27079306,('C','A')),('s2',27079366,('T','C')),('s3',27079666,('A','T')),('s4',27079826,('D','G')),('s5',27080076,('C','G')),('s6',27080275,('D','A')),('s7',27080279,('G','D')),('s8',27080526,('G','A'))]
pos_to_sites={p:[] for _,p,_ in sites}
for i,(n,p,als) in enumerate(sites): pos_to_sites[p].append(i)
read_calls=collections.defaultdict(dict)
read_rows={}
for line in text.splitlines():
    if not line or line.startswith('@'): continue
    flds=line.split('\\t')
    if len(flds)<11 or flds[2]"'!='"'chr22' or flds[5]=='*': continue
    qname=flds[0]; pos=int(flds[3]); cigar=flds[5]; seq=flds[9]
    calls={}; ref=pos; q=0
    for num,op in re.findall(r'(\\d+)([MIDNSHP=X])', cigar):
        n=int(num)
        if op in 'M=X':
            for i in range(n):
                p=ref+i
                if p in pos_to_sites:
                    for si in pos_to_sites[p]: calls[si]=seq[q+i]
            ref+=n; q+=n
        elif op=='D':
            for i in range(n):
                p=ref+i
                if p in pos_to_sites:
                    for si in pos_to_sites[p]: calls[si]='D'
            ref+=n
        elif op=='I':
            q+=n
        elif op=='N': ref+=n
        elif op=='S': q+=n
    for si,a in calls.items():
        if a in sites[si][2]:
            # if one read pair has duplicate same-site calls, keep if consistent
            if si in read_calls[qname] and read_calls[qname][si]"'!=a:
                read_calls[qname][si]='"'?'
            else:
                read_calls[qname][si]=a
for q in list(read_calls):
    read_calls[q]={i:a for i,a in read_calls[q].items() if a"'!='"'?'}
# site counts per reads
print('site_counts')
for i,s in enumerate(sites):
    c=collections.Counter(calls.get(i) for calls in read_calls.values() if i in calls)
    print(i,s,c)
print('\\nadjacent cooccurrence')
for i in range(len(sites)-1):
    tab=collections.Counter()
    for calls in read_calls.values():
        if i in calls and i+1 in calls:
            tab[(calls[i],calls[i+1])]+=1
    print(i,'->',i+1,sites[i][0],sites[i+1][0],dict(tab))
print('\\nall useful pair links')
for i,j in itertools.combinations(range(len(sites)),2):
    tab=collections.Counter()
    for calls in read_calls.values():
        if i in calls and j in calls:
            tab[(calls[i],calls[j])]+=1
    if tab:
        print(i,j,dict(tab))
